cy.get("body").should("be.visible");
cy.softAssert(() => {
    cy.get("body").then(($body) => {
        const text = $body.text();
        expect(text.match(/transaction|debit|credit|₦/i) ||
            text.match(/no transaction|empty/i)).to.be.ok;
    });
}, "Transaction list or empty state");
cy.assertAll();

cy.contains(/debit|filter/i, { timeout: 8000 }).first().click();
cy.softAssert(() => {
    cy.contains(/debit/i).should("be.visible");
}, "Debit filter active");
cy.assertAll();

// Intercept BEFORE visiting so it catches the initial data fetch
cy.intercept("GET", "**/transactions**", {
    statusCode: 200,
    body: { success: true, data: { items: [], total: 0 } },
}).as("emptyTxn");
cy.login();
cy.visit("/transactions");
cy.wait("@emptyTxn");
cy.softAssert(() => {
    cy.contains(/no transaction|empty|nothing/i, { timeout: 8000 }).should("be.visible");
}, "Empty state shown");
cy.assertAll();

// Intercept BEFORE visiting so it catches the initial data fetch
cy.intercept("GET", "**/transactions**", {
    statusCode: 500,
    body: { success: false, message: "Server error" },
}).as("txnError");
cy.login();
cy.visit("/transactions");
cy.wait("@txnError");
cy.get("body").should("be.visible");
